-- Documentation of the schema generated by Hibernate/JPA.
-- The application uses spring.jpa.hibernate.ddl-auto=update.

CREATE TABLE users (
    id BIGINT NOT NULL AUTO_INCREMENT,
    username VARCHAR(50) NOT NULL,
    normalized_username VARCHAR(50) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    email VARCHAR(254) NULL,
    normalized_email VARCHAR(254) NULL,
    phone VARCHAR(20) NULL,
    normalized_phone VARCHAR(20) NULL,
    token_version BIGINT NOT NULL DEFAULT 0,
    created_at DATETIME(6) NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_normalized_username UNIQUE (normalized_username),
    CONSTRAINT uk_users_normalized_email UNIQUE (normalized_email),
    CONSTRAINT uk_users_normalized_phone UNIQUE (normalized_phone),
    CONSTRAINT ck_users_contact CHECK (email IS NOT NULL OR phone IS NOT NULL)
);

CREATE TABLE articles (
    id BIGINT NOT NULL AUTO_INCREMENT,
    title VARCHAR(300) NOT NULL,
    normalized_title VARCHAR(300) NOT NULL,
    abstract_text VARCHAR(5000) NOT NULL,
    body LONGTEXT NOT NULL,
    created_at DATETIME(6) NOT NULL,
    author_id BIGINT NOT NULL,
    CONSTRAINT pk_articles PRIMARY KEY (id),
    CONSTRAINT uk_articles_normalized_title UNIQUE (normalized_title),
    CONSTRAINT fk_articles_author FOREIGN KEY (author_id) REFERENCES users (id)
);

CREATE INDEX idx_articles_author ON articles (author_id);

CREATE TABLE article_references (
    id BIGINT NOT NULL AUTO_INCREMENT,
    source_article_id BIGINT NOT NULL,
    referenced_article_id BIGINT NOT NULL,
    reference_position INT NOT NULL,
    CONSTRAINT pk_article_references PRIMARY KEY (id),
    CONSTRAINT uk_article_reference_pair UNIQUE (source_article_id, referenced_article_id),
    CONSTRAINT uk_article_reference_position UNIQUE (source_article_id, reference_position),
    CONSTRAINT fk_article_references_source FOREIGN KEY (source_article_id) REFERENCES articles (id),
    CONSTRAINT fk_article_references_target FOREIGN KEY (referenced_article_id) REFERENCES articles (id)
);

CREATE INDEX idx_article_references_target ON article_references (referenced_article_id);
